static bool
aui_lexbor_static_d8f79466e9_lxb_css_property_state_gradient_position_component(
    lxb_css_parser_t *parser, const lxb_css_syntax_token_t *token,
    double *pct_out)
{
    if (token == NULL) return false;

    if (token->type == LXB_CSS_SYNTAX_TOKEN_PERCENTAGE) {
        *pct_out = lxb_css_syntax_token_percentage(token)->num;
        lxb_css_syntax_parser_consume(parser);
        return true;
    }

    if (aui_lexbor_static_d8f79466e9_lxb_css_property_state_ident_is(token, "center", 6)) {
        *pct_out = 50.0;
    }
    else if (aui_lexbor_static_d8f79466e9_lxb_css_property_state_ident_is(token, "left", 4)
             || aui_lexbor_static_d8f79466e9_lxb_css_property_state_ident_is(token, "top", 3))
    {
        *pct_out = 0.0;
    }
    else if (aui_lexbor_static_d8f79466e9_lxb_css_property_state_ident_is(token, "right", 5)
             || aui_lexbor_static_d8f79466e9_lxb_css_property_state_ident_is(token, "bottom", 6))
    {
        *pct_out = 100.0;
    }
    else {
        return false;
    }

    lxb_css_syntax_parser_consume(parser);
    return true;
}

