static bool
aui_lexbor_static_d8f79466e9_lxb_css_animation_parse_name(lxb_css_parser_t *parser,
                             const lxb_css_syntax_token_t *token,
                             lxb_css_property_animation_t *animation)
{
    if (token->type == LXB_CSS_SYNTAX_TOKEN_IDENT) {
        if (aui_lexbor_static_d8f79466e9_lxb_css_animation_ident_is(token, "none", 4)) {
            animation->has_name = false;
            lxb_css_syntax_parser_consume(parser);
            return true;
        }
        lxb_css_parser_string_dup_m(parser, token, &animation->name,
                                    parser->memory->mraw);
        animation->has_name = true;
        lxb_css_syntax_parser_consume(parser);
        return true;
    }

    if (token->type == LXB_CSS_SYNTAX_TOKEN_STRING) {
        lxb_css_parser_string_dup_m(parser, token, &animation->name,
                                    parser->memory->mraw);
        animation->has_name = true;
        lxb_css_syntax_parser_consume(parser);
        return true;
    }

    return false;
}

bool
lxb_css_property_state_animation(lxb_css_parser_t *parser,
                                 const lxb_css_syntax_token_t *token,
                                 void *ctx)
{
    bool consumed = false;
    bool duration_set = false;
    bool delay_set = false;
    bool timing_set = false;
    bool iteration_set = false;
    bool direction_set = false;
    bool fill_set = false;
    bool play_set = false;
    bool name_set = false;
    lxb_css_rule_declaration_t *declar = (lxb_css_rule_declaration_t *) (ctx);
    lxb_css_property_animation_t *animation = declar->u.animation;

    while (token != NULL) {
        double seconds = 0.0;

        if (!duration_set &&
            aui_lexbor_static_d8f79466e9_lxb_css_animation_parse_time(parser, token, &seconds)) {
            animation->duration_s = seconds;
            duration_set = true;
            consumed = true;
            token = lxb_css_syntax_parser_token_wo_ws(parser);
            continue;
        }
        if (duration_set && !delay_set &&
            aui_lexbor_static_d8f79466e9_lxb_css_animation_parse_time(parser, token, &seconds)) {
            animation->delay_s = seconds;
            delay_set = true;
            consumed = true;
            token = lxb_css_syntax_parser_token_wo_ws(parser);
            continue;
        }

        if (token->type == LXB_CSS_SYNTAX_TOKEN_NUMBER && !iteration_set) {
            animation->iteration_count = lxb_css_syntax_token_number(token)->num;
            iteration_set = true;
            consumed = true;
            lxb_css_syntax_parser_consume(parser);
            token = lxb_css_syntax_parser_token_wo_ws(parser);
            continue;
        }

        if (token->type == LXB_CSS_SYNTAX_TOKEN_IDENT) {
            if (!timing_set &&
                aui_lexbor_static_d8f79466e9_lxb_css_animation_parse_timing(token, &animation->timing)) {
                timing_set = true;
                consumed = true;
                lxb_css_syntax_parser_consume(parser);
            }
            else if (!iteration_set &&
                     aui_lexbor_static_d8f79466e9_lxb_css_animation_ident_is(token, "infinite", 8)) {
                animation->iteration_count = 0.0;
                iteration_set = true;
                consumed = true;
                lxb_css_syntax_parser_consume(parser);
            }
            else if (!direction_set &&
                     aui_lexbor_static_d8f79466e9_lxb_css_animation_parse_direction(token, &animation->direction)) {
                direction_set = true;
                consumed = true;
                lxb_css_syntax_parser_consume(parser);
            }
            else if (!fill_set &&
                     aui_lexbor_static_d8f79466e9_lxb_css_animation_parse_fill_mode(token, &animation->fill_mode)) {
                fill_set = true;
                consumed = true;
                lxb_css_syntax_parser_consume(parser);
            }
            else if (!play_set &&
                     aui_lexbor_static_d8f79466e9_lxb_css_animation_parse_play_state(token, &animation->play_state)) {
                play_set = true;
                consumed = true;
                lxb_css_syntax_parser_consume(parser);
            }
            else if (!name_set &&
                     aui_lexbor_static_d8f79466e9_lxb_css_animation_parse_name(parser, token, animation)) {
                name_set = true;
                consumed = true;
            }
            else {
                break;
            }

            token = lxb_css_syntax_parser_token_wo_ws(parser);
            continue;
        }

        if (!name_set &&
            token->type == LXB_CSS_SYNTAX_TOKEN_STRING &&
            aui_lexbor_static_d8f79466e9_lxb_css_animation_parse_name(parser, token, animation)) {
            name_set = true;
            consumed = true;
            token = lxb_css_syntax_parser_token_wo_ws(parser);
            continue;
        }

        break;
    }

    if (consumed && (token == NULL
            || token->type == LXB_CSS_SYNTAX_TOKEN__END))
    {
        return lxb_css_parser_success(parser);
    }

    return lxb_css_parser_failed(parser);
}

