    bad = lxb_css_rule_bad_style_create(parser->memory);
    if (bad == NULL) {
        return lxb_css_parser_memory_fail_status(parser);
    }

    bad->declarations = (lxb_css_rule_declaration_list_t *) (ctx);

    offset = lxb_css_parser_qualified_rule_offset(parser);

