    rule->state = rule->cbx.cb->state;

    rule->skip_consume = false;
    rule->important = false;
    rule->failed = false;

    decl = &rule->u.declarations;

    decl->name_begin = 0;
    decl->name_end = 0;
    decl->value_begin = 0;
