lxb_status_t
lxb_html_document_stylesheet_attach(lxb_html_document_t *document,
                                    lxb_css_stylesheet_t *sst)
{
    lxb_status_t status;

    status = lexbor_array_push(document->css.stylesheets, sst);
    if (status != LXB_STATUS_OK) {
        return status;
    }

    return lxb_html_document_stylesheet_apply(document, sst);
}

lxb_status_t
lxb_html_document_stylesheet_apply(lxb_html_document_t *document,
                                   lxb_css_stylesheet_t *sst)
{
    lxb_status_t status = LXB_STATUS_OK;
    lxb_css_rule_t *rule;
    lxb_css_rule_list_t *list;

    rule = sst->root;

    if (rule->type != LXB_CSS_RULE_LIST) {
        return LXB_STATUS_ERROR_WRONG_ARGS;
    }

    list = lxb_css_rule_list(rule);
    rule = list->first;

    while (rule != NULL) {
        switch (rule->type) {
            case LXB_CSS_RULE_STYLE:
                status = lxb_html_document_style_attach(document,
                                                        lxb_css_rule_style(rule));
                break;

            default:
                break;
        }

        if (status != LXB_STATUS_OK) {
            /* FIXME: what to do with an error? */
        }

        rule = rule->next;
    }

    return LXB_STATUS_OK;
}

lxb_status_t
lxb_html_document_stylesheet_add(lxb_html_document_t *document,
                                 lxb_css_stylesheet_t *sst)
{
    if (sst == NULL) {
        return LXB_STATUS_OK;
    }

    return lexbor_array_push(document->css.stylesheets, sst);
}

lxb_status_t
lxb_html_document_stylesheet_remove(lxb_html_document_t *document,
                                    lxb_css_stylesheet_t *sst)
{
    size_t i, length;
    lxb_status_t status = LXB_STATUS_OK;
    lxb_css_rule_t *rule;
    lxb_css_rule_list_t *list;
    lxb_css_stylesheet_t *sst_in;

    rule = sst->root;

    if (rule->type != LXB_CSS_RULE_LIST) {
        return LXB_STATUS_ERROR_WRONG_ARGS;
    }

    list = lxb_css_rule_list(rule);
    rule = list->first;

    while (rule != NULL) {
        switch (rule->type) {
            case LXB_CSS_RULE_STYLE:
                status = lxb_html_document_style_remove(document,
                                                        lxb_css_rule_style(rule));
                break;

            default:
                break;
        }

        if (status != LXB_STATUS_OK) {
            /* FIXME: what to do with an error? */
        }

        rule = rule->next;
    }

    length = lexbor_array_length(document->css.stylesheets);

    for (i = 0; i < length; i++) {
        sst_in = lexbor_array_get(document->css.stylesheets, i);

        if (sst_in == sst) {
            lexbor_array_delete(document->css.stylesheets, i, 1);
            length = lexbor_array_length(document->css.stylesheets);
        }
    }

    return LXB_STATUS_OK;
}

lxb_status_t
lxb_html_document_element_styles_attach(lxb_html_element_t *element)
{
    lxb_status_t status = LXB_STATUS_OK;
    lxb_css_rule_t *rule;
    lexbor_array_t *ssts;
    lxb_css_rule_list_t *list;
    lxb_css_stylesheet_t *sst;
    lxb_html_document_t *document;

    document = lxb_html_element_document(element);
    ssts = document->css.stylesheets;

    for (size_t i = 0; i < lexbor_array_length(ssts); i++) {
        sst = lexbor_array_get(ssts, i);

        list = lxb_css_rule_list(sst->root);
        rule = list->first;

        while (rule != NULL) {
            switch (rule->type) {
                case LXB_CSS_RULE_STYLE:
                    status = lxb_html_document_style_attach_by_element(document,
                                             element, lxb_css_rule_style(rule));
                    break;

                default:
                    break;
            }

            if (status != LXB_STATUS_OK) {
                /* FIXME: what to do with an error? */
            }

            rule = rule->next;
        }
    }

    return LXB_STATUS_OK;
}

/*
 * Free an element's ENTIRE style AVL with a post-order walk: children first,
 * then the node, so we never follow a freed link and never rebalance. Used when
 * an element is removed from the tree — it keeps no styles, so a full release is
 * correct. The memory-safe counterpart to driving lexbor_avl_remove_by_node
 * from lexbor_avl_foreach (see aui_lexbor_static_2978fd58b1_lxb_html_document_event_remove).
 */
static void
aui_lexbor_static_2978fd58b1_lxb_html_element_style_avl_destroy(lxb_html_document_t *document,
                                   lxb_html_style_node_t *style)
{
    lxb_html_style_weak_t *weak, *next;

    if (style == NULL) {
        return;
    }

    aui_lexbor_static_2978fd58b1_lxb_html_element_style_avl_destroy(document,
                            (lxb_html_style_node_t *) style->entry.left);
    aui_lexbor_static_2978fd58b1_lxb_html_element_style_avl_destroy(document,
                            (lxb_html_style_node_t *) style->entry.right);

    weak = style->weak;

    while (weak != NULL) {
        next = weak->next;

        /* ref_dec, NOT ref_dec_destroy: detaching an element releases a
           non-owning cross-link to a stylesheet-owned rule; the rule is freed
           once, with its stylesheet's arena, never by a detach. */
        lxb_css_rule_ref_dec((lxb_css_rule_t *) (weak->value));
        lexbor_dobject_free(document->css.weak, weak);

        weak = next;
    }

    lxb_css_rule_ref_dec((lxb_css_rule_t *) (style->entry.value));
    lexbor_dobject_free(document->css.styles->nodes, style);
}

lxb_status_t
lxb_html_document_element_styles_rematch(lxb_html_element_t *element)
{
    lxb_status_t status;
    lxb_html_document_t *document;

    if (element == NULL) {
        return LXB_STATUS_ERROR_WRONG_ARGS;
    }

    document = lxb_html_element_document(element);

    /*
     * Re-match the element's styles by BUILDING UP from scratch, never removing
     * in place.
     *
     * A rematch must re-run selector matching while preserving the element's
     * inline "style=" attachment (it carries sp_s != 0, the highest specificity;
     * drop it and inline "style=flex:..." sizing is lost, collapsing laid-out
     * boxes). The old path pruned selector entries in place by driving
     * detach_all_not() from lexbor_avl_foreach(), but that read freed nodes when
     * a removal rebalanced the AVL mid-iteration (ASAN use-after-poison, hit by
     * docking re-parents that change which descendant selectors match), and
     * lexbor's rotate_for_delete cannot be driven safely across a batch of
     * removals. So instead:
     *
     *   1. release every current attachment with a safe post-order walk (no
     *      rebalancing, no iterate-while-removing);
     *   2. re-attach every stylesheet selector match;
     *   3. re-attach the element's cached inline declaration list. element->list
     *      is kept current by the style-attribute set_value event
     *      (lxb_html_element_style_parse) and is NOT touched by the teardown, so
     *      no re-parse is needed; sp_up_s(0) matches the inline specificity used
     *      at parse time.
     *
     * Every step only inserts (avl_insert) or frees the whole tree — never the
     * single-node removal that was unsafe.
     */
    if (element->style != NULL) {
        aui_lexbor_static_2978fd58b1_lxb_html_element_style_avl_destroy(document,
                                (lxb_html_style_node_t *) element->style);
        element->style = NULL;
    }

    status = lxb_html_document_element_styles_attach(element);
    if (status != LXB_STATUS_OK) {
        return status;
    }

    if (element->list != NULL) {
        status = lxb_html_element_style_list_append(element, element->list,
                                                lxb_css_selector_sp_up_s(0));
    }

    return status;
}

void
lxb_html_document_stylesheet_destroy_all(lxb_html_document_t *document,
                                         bool destroy_memory)
{
    size_t length;
    lxb_css_stylesheet_t *sst;
    lxb_html_document_css_t *css = &document->css;

    length = lexbor_array_length(css->stylesheets);

    for (size_t i = 0; i < length; i++) {
        sst = lexbor_array_pop(css->stylesheets);

        (void) lxb_css_stylesheet_destroy(sst, destroy_memory);
    }
}

