                    p.present = true;
                    p.floating = true;
                    p.x = nx - fd.cb_x;
                    p.y = ny - fd.cb_y;
                    p.w = fd.elem_w;
                    p.h = fd.elem_h;
                    impl_->dock_overrides[fd.panel_id] = p;
                    detail::dock_trace("float-move panel=" + fd.panel_id +
                               " rect=(" + std::to_string(p.x) + "," +
                               std::to_string(p.y) + "," +
                               std::to_string(p.w) + "x" +
                               std::to_string(p.h) + ")");
