// ────────────────────────────────────────────────────────────────────────
// src/framework/imm/reconciler.cpp
// ────────────────────────────────────────────────────────────────────────
// Virtual DOM reconciler (React-style).
//
// Given prev_tree and new_tree (both built by the imm calls), produce
// the minimal patch sequence to transform the retained DOM into the
// shape of new_tree:
//
//   Patch ops:
//     - INSERT(node, parent, index)
//     - REMOVE(node)
//     - MOVE(node, new_index)
//     - SET_ATTR(node, name, value)
//     - REMOVE_ATTR(node, name)
//     - SET_TEXT(node, text)
//     - REPLACE_HANDLER(node, event, fn_id)
//
// Patches are then applied to lexbor's DOM via its mutation API.
//
// Keying: by default the call-site path; explicit .key(...) overrides
// for keyed-children semantics matching React.

namespace affineui::imm {

void reconciler_stub() {
    // intentional no-op
}

}  // namespace affineui::imm

// ────────────────────────────────────────────────────────────────────────
// src/framework/imm/state_store.cpp
// ────────────────────────────────────────────────────────────────────────
// State store for use_state<T> / use_effect.
//
// Keyed by the call-site path hash. Each slot owns a destructor and
// raw bytes for T. On reconciliation, slots whose owning nodes
// disappeared for at least one full pass get their destructors invoked
// and storage reclaimed (React-style unmount cleanup).
//
// Threading: only the bound document's frame thread touches the store
// during a reconciliation pass; mutations from event handlers are
// queued and applied at pass boundaries.

namespace affineui::imm {

void state_store_stub() {
    // intentional no-op
}

}  // namespace affineui::imm

// ────────────────────────────────────────────────────────────────────────
// src/c_api.cpp
// ────────────────────────────────────────────────────────────────────────
// Thin extern "C" surface mirroring the C++ API.
//
// Lets bindings from Rust / Zig / Odin / Python ctypes drive AffineUI
// without a C++ ABI dance. Functions are named affineui_<verb_object>;
// opaque handle types are `affineui_<type>*`.




namespace {

affineui::Backend to_cpp_backend(affineui_backend b) {
    switch (b) {
        case AFFINEUI_GPU_METAL: return affineui::Backend::metal;
        case AFFINEUI_GPU_GL:    return affineui::Backend::gl;
        case AFFINEUI_GPU_WGPU:  return affineui::Backend::wgpu;
        case AFFINEUI_GPU_D3D11:
        default:                 return affineui::Backend::d3d11;
    }
}

affineui::PixelFormat to_cpp_format(int f) {
    switch (f) {
        case AFFINEUI_FORMAT_RGBA8:         return affineui::PixelFormat::rgba8;
        case AFFINEUI_FORMAT_BGRA8:         return affineui::PixelFormat::bgra8;
        case AFFINEUI_FORMAT_DEPTH:         return affineui::PixelFormat::depth;
        case AFFINEUI_FORMAT_DEPTH_STENCIL: return affineui::PixelFormat::depth_stencil;
        case AFFINEUI_FORMAT_DEFAULT:
        default:                            return affineui::PixelFormat::default_;
    }
}

// The C log callback can't bind directly to the C++ LogFn (enum types
// differ), so stash it and route through a static thunk.
affineui_log_fn g_c_log      = nullptr;
void*           g_c_log_user = nullptr;

void cpp_log_thunk(affineui::LogLevel level, const char* msg, void* /*user*/) {
    if (g_c_log) {
        g_c_log(static_cast<affineui_log_level>(static_cast<int>(level)), msg, g_c_log_user);
    }
}

}  // namespace

